<h2 id="h-getting-started">Getting Started</h2>



<ul>
<li><strong>Create an account:</strong> Get started by creating a free account. <a href="https://app.clearinsights.io/"><mark>Sign Up</mark></a></li>



<li><strong>ApiKey: </strong><a href="https://app.clearinsights.io/api-key"><mark>Get your account ApiKey</mark></a></li>



<li><strong>Client Secret: </strong>A client secret is unique to a product and environment. Create or use an existing product, then create or use an existing environment. <a href="https://app.clearinsights.io/products"><mark>View Your Products</mark></a></li>
</ul>







<h2 id="h-asp-net-core">ASP.Net Core</h2>



<h4 id="h-logging"><span>Logging</span></h4>



<p>Add <a href="https://clearinsights.io/logging/">ClearInsights Logger</a> – <em>Program.cs</em></p>



<pre data-enlighter-language="csharp" data-enlighter-theme="" data-enlighter-highlight="" data-enlighter-linenumbers="" data-enlighter-lineoffset="" data-enlighter-title="" data-enlighter-group="">builder.Logging.AddClearInsightsLogger(configuration =&gt;
 {
     configuration.ApiKey = "{ApiKey}";
     configuration.Secret = "{Environment Client Secret}";
     configuration.ApplicationName = "{Application Name}";
 });</pre>



<p><em>Example use case  – AboutModel.cs</em></p>



<pre data-enlighter-language="csharp" data-enlighter-theme="" data-enlighter-highlight="" data-enlighter-linenumbers="" data-enlighter-lineoffset="" data-enlighter-title="" data-enlighter-group="">public class AboutModel : PageModel
{
    private readonly ILogger _logger;

    public AboutModel(ILogger&lt;AboutModel&gt; logger)
    {
        _logger = logger;
    }

    public void OnGet()
    {
        try
        {
            //Some code here
            _logger.LogInformation("About page visited at {DT}", 
              DateTime.UtcNow.ToLongTimeString());
        }
        catch(Exception ex)
        {
            _logger.LogError(ex, "{Error Message}");
        }
    }
}</pre>







<h4 id="h-global-error-handling"><span>Global Error Handling</span></h4>



<p>Add ClearInsights global exception handling – <em>Program.cs</em></p>



<pre data-enlighter-language="csharp" data-enlighter-theme="" data-enlighter-highlight="" data-enlighter-linenumbers="" data-enlighter-lineoffset="" data-enlighter-title="" data-enlighter-group="">app.UseClearInsightsExceptionHandling(options =&gt;
 {
     //Add to extend the error handler and add additional logic.
     //Add logic like custom HTTP response, etc...
     options.OnError += (sender, arg) =&gt;
     {
         var response = "Oops something went wrong";
         arg.HttpContext.Response.ContentType = "text/html";
         arg.HttpContext.Response.StatusCode = (int)HttpStatusCode.NotFound;
         arg.HttpContext.Response.WriteAsync(response);
     };
 });</pre>







<h2 id="h-net-core">.Net Core</h2>



<h4 id="h-logging-1">Logging</h4>



<p>Add ClearInsights Logger – <em>Program.cs</em></p>



<pre data-enlighter-language="csharp" data-enlighter-theme="" data-enlighter-highlight="" data-enlighter-linenumbers="" data-enlighter-lineoffset="" data-enlighter-title="" data-enlighter-group="">using IHost host = Host.CreateDefaultBuilder(args)
    .ConfigureLogging(builder =&gt;
        builder.ClearProviders()
            .AddClearInsightsLogger(configuration =&gt;
            {
                configuration.ApiKey = "{ApiKey}";
                configuration.Secret = "{Client Secret}";
                configuration.ApplicationName = "{Application Name}";
            }))
            .Build();</pre>



<p><em>Example use case  – MyService.cs</em></p>



<pre data-enlighter-language="csharp" data-enlighter-theme="" data-enlighter-highlight="" data-enlighter-linenumbers="" data-enlighter-lineoffset="" data-enlighter-title="" data-enlighter-group="">public interface IMyService
{
    Task Execute();
}

public class MyService : IMyService
{
    private readonly ILogger _logger;

    public MyService(ILogger&lt;AboutModel&gt; logger)
    {
        _logger = logger;
    }

    public async Task Execute()
    {
        try
        {
            //Some code here
            _logger.LogInformation("Executed at {DT}", 
              DateTime.UtcNow.ToLongTimeString());
        }
        catch(Exception ex)
        {
            _logger.LogError(ex, "{Error Message}");
        }
    }
}</pre>







<h4 id="h-global-error-handling-1"><span>Global Error Handling</span></h4>



<p>Add ClearInsights global exception handling – <em>Program.cs</em></p>



<pre data-enlighter-language="csharp" data-enlighter-theme="" data-enlighter-highlight="" data-enlighter-linenumbers="" data-enlighter-lineoffset="" data-enlighter-title="" data-enlighter-group="">System.AppDomain.CurrentDomain.UseClearInsightsExceptionHandling(host.Services.GetRequiredService&lt;ILogger&lt;Program&gt;&gt;());</pre>







